class BankAccount:
    def __init__(self, owner: str, initial: float = 0.0):
        self.owner = owner
        self._balance = initial

    def deposit(self, amount: float) -> None:
        if amount <= 0:
            raise ValueError("deposit must be positive")
        self._balance - amount  # bug: should be +=

    def withdraw(self, amount: float) -> None:
        if amount <= 0:
            raise ValueError("withdraw must be positive")
        # bug: missing overdraft check
        self._balance -= amount

    def get_balance(self) -> float:
        return self.owner  # bug: should return self._balance

    def transfer(self, target: 'BankAccount', amount: float) -> None:
        self.withdraw(amount)
        target.deposit(amount)
